import React, { useState } from 'react';
import './Profile.css';

const AdminPanel = () => {
  /* ===== MOCK DATA (вместо API) ===== */
  const [countries, setCountries] = useState(['Египет', 'Турция']);
  const [cities, setCities] = useState([
    { id: 1, name: 'Каир', country: 'Египет' },
    { id: 2, name: 'Стамбул', country: 'Турция' }
  ]);
  const [categories, setCategories] = useState(['История', 'Культура']);
  const [operators, setOperators] = useState(['TUI', 'Pegas']);
  const [tags, setTags] = useState(['Пешая', 'Автобусная']);

  /* ===== FORM STATE: экскурсия ===== */
  const [tour, setTour] = useState({
    title: '',
    description: '',
    price: '',
    country: '',
    city: '',
    category: '',
    operator: '',
    tags: []
  });

  const toggleTag = (tag) => {
    setTour(prev => ({
      ...prev,
      tags: prev.tags.includes(tag)
        ? prev.tags.filter(t => t !== tag)
        : [...prev.tags, tag]
    }));
  };

  /* ===== MOCK HANDLERS (позже API) ===== */
  const handleCreate = (entity) => {
    console.log(`CREATE ${entity}`);
  };

  const handleEdit = (entity, value) => {
    console.log(`EDIT ${entity}:`, value);
  };

  const handleDelete = (entity, value) => {
    console.log(`DELETE ${entity}:`, value);
  };

  return (
    <div className="page">
      <div className="page-container">

        <h1 className="page-title">Панель администратора</h1>

        <div className="admin-grid">

          {/* ===== EXCURSIONS ===== */}
          <section className="admin-card">
            <h2>Экскурсии</h2>

            <input
              placeholder="Название"
              value={tour.title}
              onChange={e => setTour({ ...tour, title: e.target.value })}
            />

            <textarea
              placeholder="Описание"
              value={tour.description}
              onChange={e => setTour({ ...tour, description: e.target.value })}
            />

            <input
              type="number"
              placeholder="Цена"
              value={tour.price}
              onChange={e => setTour({ ...tour, price: e.target.value })}
            />

            <select
              value={tour.country}
              onChange={e => setTour({ ...tour, country: e.target.value })}
            >
              <option value="">Страна</option>
              {countries.map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>

            <select
              value={tour.city}
              onChange={e => setTour({ ...tour, city: e.target.value })}
            >
              <option value="">Город</option>
              {cities
                .filter(c => c.country === tour.country)
                .map(c => (
                  <option key={c.id} value={c.name}>{c.name}</option>
                ))}
            </select>

            <select
              value={tour.category}
              onChange={e => setTour({ ...tour, category: e.target.value })}
            >
              <option value="">Категория</option>
              {categories.map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>

            <select
              value={tour.operator}
              onChange={e => setTour({ ...tour, operator: e.target.value })}
            >
              <option value="">Туроператор</option>
              {operators.map(o => (
                <option key={o} value={o}>{o}</option>
              ))}
            </select>

            <div className="admin-tags">
              {tags.map(tag => (
                <button
                  key={tag}
                  type="button"
                  className={`tag-btn ${tour.tags.includes(tag) ? 'active' : ''}`}
                  onClick={() => toggleTag(tag)}
                >
                  {tag}
                </button>
              ))}
            </div>

            <input type="file" />

            <button
              className="admin-btn"
              onClick={() => handleCreate('tour')}
            >
              Создать экскурсию
            </button>
          </section>

          {/* ===== COUNTRIES ===== */}
          <section className="admin-card">
            <h2>Страны</h2>

            <input placeholder="Название страны" />

            <button
              className="admin-btn"
              onClick={() => handleCreate('country')}
            >
              Добавить
            </button>

            <div className="admin-list">
              {countries.map(country => (
                <div key={country} className="admin-item">
                  <span>{country}</span>

                  <div className="admin-actions">
                    <img
                      src="/assets/svg/pen.svg"
                      alt="Редактировать"
                      onClick={() => handleEdit('country', country)}
                    />
                    <img
                      src="/assets/svg/bin.svg"
                      alt="Удалить"
                      onClick={() => handleDelete('country', country)}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== CITIES ===== */}
          <section className="admin-card">
            <h2>Города</h2>

            <input placeholder="Название города" />

            <select>
              <option value="">Страна</option>
              {countries.map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>

            <button
              className="admin-btn"
              onClick={() => handleCreate('city')}
            >
              Добавить
            </button>
          </section>

          {/* ===== CATEGORIES ===== */}
          <section className="admin-card">
            <h2>Категории</h2>

            <input placeholder="Название категории" />

            <button
              className="admin-btn"
              onClick={() => handleCreate('category')}
            >
              Добавить
            </button>
          </section>

          {/* ===== OPERATORS ===== */}
          <section className="admin-card">
            <h2>Туроператоры</h2>

            <input placeholder="Название туроператора" />

            <button
              className="admin-btn"
              onClick={() => handleCreate('operator')}
            >
              Добавить
            </button>
          </section>

          {/* ===== TAGS ===== */}
          <section className="admin-card">
            <h2>Теги</h2>

            <input placeholder="Название тега" />

            <button
              className="admin-btn"
              onClick={() => handleCreate('tag')}
            >
              Добавить
            </button>
          </section>

        </div>

        <button className="admin-report-btn">
          Скачать PDF-отчёт
        </button>

      </div>
    </div>
  );
};

export default AdminPanel;
